actions.script:
def values = [templateId:templateId]
// Explicit fields preserve billing policies and organization ownership.
['facilityId','templateName','companyName','addressLine1','addressLine2','city','state','pincode','phone','email',
 'taxRegistrationNumber','receiptWidth','showLogo','logoUrl','showTaxBreakdown','showDiscount',
 'showCustomerInfo','showPaymentDetails','showItemTax','isDefault','isActive'].each { key ->
    if (ec.web.parameters.containsKey(key)) values[key] = ec.web.parameters.get(key)
}
['templateName','companyName'].each { key ->
    if (values.containsKey(key) && !values[key]?.toString()?.trim()) ec.message.addError(key+' is required.')
}
['showLogo','showTaxBreakdown','showDiscount','showCustomerInfo','showPaymentDetails','showItemTax','isDefault','isActive'].each { key ->
    if(values.containsKey(key) && !(values[key] in ['Y','N'])) ec.message.addError('Choose Yes or No for '+key)
}
values.each { key,value -> if (value != null && value.toString().length()>255) ec.message.addError('Receipt field is too long: '+key) }
if (values.logoUrl && !(values.logoUrl.toString() ==~ /https:\/\/[^\s]+|\/(?!\/)[^\s]*/)) ec.message.addError('Use an HTTPS logo URL or an existing application image path.')
def tpl = ec.entity.find('zenith.erp.pos.PosReceiptTemplate').condition('templateId',templateId).one()
ec.entity.find('mantle.party.Party').condition('partyId',tpl.organizationPartyId).forUpdate(true).one()
if (ec.web.parameters.containsKey('optionsJson')) {
    def resolved=ec.service.sync().name('zenith.pos.ReceiptTemplateServices.resolve#ReceiptOptions')
        .parameters([storedJson:tpl.receiptOptionsJson,receiptDesign:receiptDesign,changesJson:ec.web.parameters.optionsJson]).call()
    values.receiptOptionsJson=resolved?.optionsJson
}
if(values.containsKey('facilityId')) {
    values.facilityId=values.facilityId ?: null
    if(values.facilityId && !ec.entity.find('mantle.facility.Facility').condition('facilityId',values.facilityId).condition('ownerPartyId',tpl.organizationPartyId).one()) ec.message.addError('Choose a shop in your organization.')
}
if (ec.message.hasError()) return
if (values.receiptWidth && !(values.receiptWidth in ['58mm','80mm'])) {
    ec.message.addError('Choose a supported receipt width.')
} else {
    ['headerText','footerText','termsText'].each { key ->
        if (ec.web.parameters.containsKey(key)) {
            def target = receiptDesign == 'normal' ? key : receiptDesign + key.substring(0,1).toUpperCase() + key.substring(1)
            def value=ec.web.parameters.get(key)?.toString() ?: ''
            if(value.length()>(key=='termsText'?4000:1000) || value.find(/[\p{Cc}&&[^\n\r\t]]/)) ec.message.addError('Receipt text is too long or contains control characters.')
            values[target] = value
        }
    }
    if (ec.message.hasError()) return
    ec.service.sync().name('update#zenith.erp.pos.PosReceiptTemplate').parameters(values).call()
}
